#include "graphics.h"
#include "disk.h"
#include "storage.h"
#include "settings.h"
#define BLUE 0x245b9eu
#define INK 0x26354bu
typedef struct {u32 start,size;int type,format;} Partition;
typedef struct {u32 start,size;int slot;} Region;
static Partition parts[4];static Region regions[9];static int region_count,selected,selected_disk=-1,size_edit,size_len,table_error;
static char size_text[12];static const char *error="";
static int system_slot=-1,data_slot=-1,copy_phase;static u32 copied,verified;
static u8 block[512],check[512],mbr[512];
int install_step,install_complete;
static int hit(int x,int y,int a,int b,int w,int h){return x>=a&&x<a+w&&y>=b&&y<b+h;}
static void button(int x,int y,int w,const char *text,int primary){g_round(x,y,w,31,4,primary?BLUE:0xe8edf5);g_center(x,y+6,w,text,primary?0xffffff:INK);}
static void size_label(u32 sectors,char *out){number(sectors/2048,out);u32 n=strlen(out);const char *s=" MB";while((*((out++)+n)=*s++)){} }
static void rows(void){int slots[4],n=0;for(int i=0;i<4;i++)if(parts[i].type)slots[n++]=i;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)if(parts[slots[j]].start<parts[slots[i]].start){int t=slots[i];slots[i]=slots[j];slots[j]=t;}region_count=0;u32 cursor=2048;for(int i=0;i<n;i++){Partition *p=&parts[slots[i]];if(p->start>cursor)regions[region_count++]=(Region){cursor,p->start-cursor,-1};regions[region_count++]=(Region){p->start,p->size,slots[i]};cursor=p->start+p->size;}if(selected_disk>=0&&cursor<disks[selected_disk].sectors&&region_count<9)regions[region_count++]=(Region){cursor,disks[selected_disk].sectors-cursor,-1};if(selected>=region_count)selected=region_count-1;}
static void load_disk(int d){selected_disk=d;selected=0;table_error=0;memset(parts,0,sizeof(parts));error="";if(d<0||!disk_read(d,0,block)){error="无法读取磁盘。";table_error=1;return;}if(block[510]==0x55&&block[511]==0xaa){for(int i=0;i<4;i++){const u8 *p=block+446+i*16;u32 start=*(const u32 *)(p+8),size=*(const u32 *)(p+12);if(!p[4])continue;if(p[4]==0xee){table_error=1;error="此磁盘使用 GPT；当前安装程序只支持 MBR。";break;}if(start<2048||!size||start>=disks[d].sectors||size>disks[d].sectors-start){table_error=1;error="分区表无效，已禁止写入此磁盘。";break;}parts[i]=(Partition){start,size,p[4],0};}for(int i=0;i<4;i++)for(int j=i+1;j<4;j++)if(parts[i].type&&parts[j].type&&parts[i].start<parts[j].start+parts[j].size&&parts[j].start<parts[i].start+parts[i].size){table_error=1;error="分区重叠，已禁止写入此磁盘。";}}else{int blank=1;for(int i=0;i<512;i++)if(block[i])blank=0;if(!blank){table_error=1;error="无法识别此磁盘的布局，已禁止自动写入。";}}rows();}
void install_open(void){install_step=install_complete=size_edit=0;error="";int d=-1;for(int i=0;i<4;i++)if(disks[i].present&&disks[i].sectors>=131072){d=i;break;}load_disk(d);}
int install_offer(void){if(*(volatile u8 *)0x4f0c>=0x80)return 0;for(int d=0;d<4;d++)if(disks[d].present&&disks[d].sectors>=131072)return 1;return 0;}
int install_can_close(void){return install_step!=5;}
static void automatic(void){if(selected_disk<0||table_error)return;for(int i=0;i<4;i++)if(parts[i].type){error="请先删除已有分区，再使用自动分区。";return;}if(disks[selected_disk].sectors<131072){error="安装至少需要 64 MB 的专用磁盘。";return;}parts[0]=(Partition){2048,32768,1,1};parts[1]=(Partition){34816,disks[selected_disk].sectors-34816,0x7f,1};selected=0;rows();error="已规划系统分区与数据分区，尚未写入磁盘。";}
static void new_partition(void){if(selected_disk<0||table_error||selected<0||selected>=region_count)return;Region *r=&regions[selected];if(r->slot>=0){error="请选择未分配空间。";return;}int have_system=0;for(int i=0;i<4;i++)if(parts[i].type==1)have_system=1;u32 mb=have_system?r->size/2048:16;if(mb>r->size/2048)mb=r->size/2048;number(mb,size_text);size_len=(int)strlen(size_text);size_edit=1;}
static void create_partition(void){u32 mb=0;for(int i=0;i<size_len;i++){if(mb>131072){error="分区大小超出范围。";return;}mb=mb*10+(u32)(size_text[i]-'0');}if(!mb){error="请输入大于零的分区大小。";return;}Region r=regions[selected];if(mb>r.size/2048){error="分区大小超过所选的未分配空间。";return;}int slot=-1,type=1;for(int i=0;i<4;i++){if(!parts[i].type&&slot<0)slot=i;if(parts[i].type==1)type=0x7f;}if(slot<0){error="MBR 最多支持四个主分区。";return;}if((type==1&&mb<4)||(type==0x7f&&mb<16)){error="系统分区至少 4 MB，数据分区至少 16 MB。";return;}parts[slot]=(Partition){r.start,mb*2048,type,1};size_edit=0;rows();error="分区已加入安装计划，尚未写入磁盘。";}
static int plan(void){system_slot=data_slot=-1;if(selected_disk<0||table_error)return 0;if(disks[selected_disk].sectors<131072){error="安装至少需要 64 MB 的专用磁盘。";return 0;}for(int i=0;i<4;i++){if(parts[i].type==1&&parts[i].size>=2880&&system_slot<0)system_slot=i;if(parts[i].type==0x7f&&parts[i].size>=16392&&data_slot<0)data_slot=i;}if(system_slot<0||data_slot<0){error="需要一个系统分区和一个 SINO 数据分区。";return 0;}if(*(volatile u8 *)0x4f0c>=0x80&&selected_disk==storage_disk){error="不能覆盖正在运行的系统，请从 ISO 光盘启动安装。";return 0;}return 1;}
static void begin(void){if(!plan())return;if(storage_ready&&storage_disk==selected_disk){if(!storage_sync()){error="当前数据磁盘无法保存，安装已停止。";return;}storage_ready=storage_dirty=0;}int file=-1;for(u32 i=0;i<file_count;i++)if(streq(files[i].name,"MBR.BIN"))file=(int)i;if(file<0||!fs_read((u32)file,mbr,512)){error="光盘缺少 MBR 引导文件。";return;}memset(mbr+446,0,64);for(int i=0;i<4;i++)if(parts[i].type){u8 *p=mbr+446+i*16;p[0]=i==system_slot?0x80:0;p[1]=p[5]=0xfe;p[2]=p[3]=p[6]=p[7]=0xff;p[4]=(u8)parts[i].type;*(u32 *)(p+8)=parts[i].start;*(u32 *)(p+12)=parts[i].size;}*(u32 *)(mbr+440)=0x53494e4f^ticks;copied=verified=0;copy_phase=0;install_step=5;error="";}
int install_poll(void){if(install_step!=5)return 0;int ok=1;u32 base=parts[system_slot].start;if(copy_phase==0){for(int n=0;n<32&&copied<2880;n++,copied++){memcpy(block,RAMDISK+copied*512,512);if(!copied){*(u32 *)(block+28)=base;block[36]=(u8)(0x80+selected_disk);}if(!disk_write(selected_disk,base+copied,block)){ok=0;break;}}if(copied==2880){ok=disk_flush(selected_disk);copy_phase=1;}}
 else if(copy_phase==1){for(int n=0;n<32&&verified<2880;n++,verified++){if(!disk_read(selected_disk,base+verified,check)){ok=0;break;}memcpy(block,RAMDISK+verified*512,512);if(!verified){*(u32 *)(block+28)=base;block[36]=(u8)(0x80+selected_disk);}for(int j=0;j<512;j++)if(check[j]!=block[j])ok=0;if(!ok)break;}if(verified==2880)copy_phase=2;}
 else {u32 data=parts[data_slot].start;memset(block,0,512);if(parts[data_slot].format){for(int i=0;i<9;i++)if(!disk_write(selected_disk,data+(u32)i,block))ok=0;if(!disk_write(selected_disk,data+8200,block))ok=0;}if(ok){u32 *p=(u32 *)block;p[0]=0x32474643;p[1]=1;p[2]=(u32)display_width;p[3]=(u32)display_height;p[4]=(u32)display_scale;p[5]=(u32)display_contrast;p[6]=(u32)settings_language;ok=disk_write(selected_disk,1,block)&&disk_flush(selected_disk);}if(ok)ok=disk_write(selected_disk,0,mbr)&&disk_flush(selected_disk);if(ok){install_complete=1;install_step=6;debug("INSTALL completed: MBR, boot partition verified, SFS data partition ready\n");}}
 if(!ok){debug("INSTALL I/O failure: phase=");debug_hex((u32)copy_phase);debug(" copied=");debug_hex(copied);debug(" verified=");debug_hex(verified);debug("\n");install_step=3;install_complete=0;error="写入或校验失败。请检查磁盘；安装未完成。";}return 1;}
static void restart(void){cli();outb(0x64,0xfe);for(;;)halt();}
