 int x=184;const char *titles[]={"语言与区域","安装 SINO 操作系统","许可与安装说明","你想将 SINO 安装在哪里？","确认安装计划","正在安装 SINO","SINO 已安装完成"};g_text(1,x,57,titles[install_step],INK);
